144		if recs[4].Decision.Request.Subject.ID != "u1" || !recs[4].Decision.Request.Subject.Disabled {
145			t.Fatalf("disabled request not stored: %+v", recs[4].Decision.Request)
146		}
147		if recs[5].Decision.Request.SubjectOrg != "globex" {
148			t.Fatalf("mismatched org request not stored: %+v", recs[5].Decision.Request)
149		}
150		// Sequences ascend and match the underlying chain positions (the
151		// publish sits at seq 2 and is filtered out of this view).
152		wantSeqs := []int{1, 3, 4, 5, 6, 7, 8}
153		gotSeqs := make([]int, len(recs))
154		for i, r := range recs {
155			gotSeqs[i] = r.Seq
156		}
157		if !reflect.DeepEqual(gotSeqs, wantSeqs) {
