61			t.Fatalf("review inconsistent: original=%+v recomputed=%+v", got.Original, got.Recomputed)
62		}
63		if !reflect.DeepEqual(got.Original, original) {
64			t.Fatalf("original = %+v, want %+v", got.Original, original)
65		}
