220		mustFail("rewrite target", func(r []AuditRecord) []AuditRecord {
221			r[1].Decision.Decision.Allowed = !r[1].Decision.Decision.Allowed
222			return r
223		}, cp)
224		mustFail("rewrite history policy", func(r []AuditRecord) []AuditRecord {
225			r[0].Change.Policies[0].Effect = EffectDeny
226			return r
227		}, cp)
228		mustFail("delete middle", func(r []AuditRecord) []AuditRecord {
229			return []AuditRecord{r[0], r[2], r[3]}
230		}, cp)
231		mustFail("delete tail after target", func(r []AuditRecord) []AuditRecord {
232			return r[:3]
233		}, cp)
234		mustFail("reorder", func(r []AuditRecord) []AuditRecord {
235			r[2], r[3] = r[3], r[2]
236			return r
237		}, cp)
238		mustFail("corruption after target", func(r []AuditRecord) []AuditRecord {
239			// Record 4 sits after the reviewed seq 2; its damage must count.
240			r[3].Decision.Request.Subject.ID = "hacker"
241			return r
242		}, cp)
243		mustFail("checkpoint fingerprint mismatch", func(r []AuditRecord) []AuditRecord { return r },
244			Checkpoint{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"})
245		mustFail("checkpoint end mismatch", func(r []AuditRecord) []AuditRecord { return r },
