432		if err != nil {
433			t.Fatal(err)
434		}
435		snapshot := append([]AuditRecord(nil), recs...)
436	
437		got, err := RecheckDecisionOffline("acme", recs, cp, 2)
438		if err != nil {
439			t.Fatal(err)
440		}
441		if !reflect.DeepEqual(recs, snapshot) {
442			t.Fatal("offline review modified the supplied records")
443		}
444		// Mutating the caller's material after the call must not reach the
445		// returned decisions.
446		recs[0].Change.Policies[0].Subject = "hacker"
447		recs[1].Decision.Decision.Matched[0] = "forged"
448		recs[1].Decision.Request.Subject.ID = "hacker"
449		if !reflect.DeepEqual(got.Original.Matched, []string{"p1"}) {
450			t.Fatalf("original decision aliases input: %+v", got.Original)
451		}
452		if !reflect.DeepEqual(got.Recomputed.Matched, []string{"p1"}) {
453			t.Fatalf("recomputed decision aliases input: %+v", got.Recomputed)
454		}
