517	// offlineBadRequest returns a request that fails exactly one envelope
518	// condition when reviewed for org, together with the online reason.
519	func offlineBadRequestCases(org string) map[string]struct {
520		modify func(OrgRequest) OrgRequest
521		reason string
522	} {
523		return map[string]struct {
524			modify func(OrgRequest) OrgRequest
525			reason string
526		}{
527			"disabled subject": {
528				modify: func(r OrgRequest) OrgRequest { r.Subject.Disabled = true; return r },
529				reason: "subject is disabled",
530			},
531			"missing subject organization": {
532				modify: func(r OrgRequest) OrgRequest { r.SubjectOrg = ""; return r },
533				reason: "missing subject organization",
534			},
535			"missing resource organization": {
536				modify: func(r OrgRequest) OrgRequest { r.ResourceOrg = ""; return r },
537				reason: "missing resource organization",
538			},
539			"subject organization mismatch": {
540				modify: func(r OrgRequest) OrgRequest { r.SubjectOrg = "globex"; return r },
541				reason: "organization mismatch",
542			},
543			"resource organization mismatch": {
544				modify: func(r OrgRequest) OrgRequest { r.ResourceOrg = "globex"; return r },
545				reason: "organization mismatch",
546			},
