653	// TestOfflineReviewRecomputedReasonPrecedenceMatchesOnline checks that when
654	// several envelope conditions fail at once, the recomputed reason and order
655	// match checkRequest exactly.
656	func TestOfflineReviewRecomputedReasonPrecedenceMatchesOnline(t *testing.T) {
657		const org = "acme"
658		// Empty subject org precedes empty resource org precedes missing ids
659		// precedes missing action; mismatches follow the missing-field block;
660		// invalid scope precedes the disabled check.
661		type precedenceCase struct {
662			modify func(OrgRequest) OrgRequest
663			reason string
664		}
665		cases := []precedenceCase{
666			{func(r OrgRequest) OrgRequest {
667				r.SubjectOrg = ""
668				r.ResourceOrg = ""
669				r.Subject.ID = ""
670				r.Resource.ID = ""
671				r.Action = ""
672				r.Subject.Disabled = true
673				return r
674			}, "missing subject organization"},
675			{func(r OrgRequest) OrgRequest {
676				r.SubjectOrg = "globex"
677				r.ResourceOrg = "other"
678				r.Action = ""
679				return r
680			}, "missing action"},
681			{func(r OrgRequest) OrgRequest {
682				r.SubjectOrg = "globex"
683				r.ResourceOrg = "other"
684				r.Resource.Scope = "org/../a"
685				r.Subject.Disabled = true
686				return r
687			}, "organization mismatch"},
688			{func(r OrgRequest) OrgRequest {
689				r.Resource.Scope = "/bad"
690				r.Subject.Disabled = true
691				return r
692			}, "invalid scope: scope \"/bad\" has a leading or trailing slash"},
693		}
694		for i, tc := range cases {
695			req := tc.modify(request(org, "u1", "r1", "org/a", "read"))
696			// What the online path would have returned for the same request.
697			online, ok := checkRequest(org, req)
698			if ok {
699				t.Fatalf("case %d request unexpectedly valid", i)
700			}
701			recs, cp := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
702				func(seq int) (string, *PolicyChange, *DecisionRecord) {
703					return AuditPolicyChange, &PolicyChange{
704						Version: 1,
705						Policies: []Policy{{ID: "p1", Subject: req.Subject.ID, Action: req.Action,
706							Scope: "org/a", Effect: EffectAllow}},
707					}, nil
708				},
709				func(seq int) (string, *PolicyChange, *DecisionRecord) {
710					return AuditDecision, nil, &DecisionRecord{
711						Request:  req,
712						Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
713					}
714				},
715			})
716			got, err := RecheckDecisionOffline(org, recs, cp, 2)
717			if err != nil {
718				t.Fatalf("case %d: %v", i, err)
719			}
720			if got.Consistent {
721				t.Fatalf("case %d unexpectedly consistent: %+v", i, got)
722			}
723			if !reflect.DeepEqual(got.Recomputed, online) {
724				t.Fatalf("case %d recomputed = %+v, want online envelope decision %+v", i, got.Recomputed, online)
725			}
726			if got.Recomputed.Reason != tc.reason {
727				t.Fatalf("case %d reason = %q, want %q", i, got.Recomputed.Reason, tc.reason)
728			}
729		}
730	}
731	
732	// TestOfflineReviewOriginalDenyStillInconsistent covers a record that does
733	// deny, but records the wrong version, reason or matched list relative to
734	// the recomputed envelope denial.
735	func TestOfflineReviewOriginalDenyStillInconsistent(t *testing.T) {
736		const org = "acme"
737		req := request(org, "u1", "r1", "org/a", "read")
738		req.Subject.Disabled = true
739	
740		variants := map[string]Decision{
741			"wrong version": {Allowed: false, Reason: "subject is disabled", Matched: nil, Version: 1},
742			"wrong reason":  {Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
743			"wrong matched": {Allowed: false, Reason: "subject is disabled", Matched: []string{"p1"}, Version: 1},
744			"allowed claim": {Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
745		}
746		for name, claim := range variants {
747			t.Run(name, func(t *testing.T) {
