749					func(seq int) (string, *PolicyChange, *DecisionRecord) {
750						return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{
751							{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
752						}}, nil
753					},
754					func(seq int) (string, *PolicyChange, *DecisionRecord) {
