825		laterRecs, laterCP := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
826			func(seq int) (string, *PolicyChange, *DecisionRecord) {
827				return AuditDecision, nil, &DecisionRecord{
